#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ll m;
    cin >> n >> m;

    vector<ll> a(n);
    ll sum = 0;
    for (ll &x : a) {
        cin >> x;
        sum += x;
    }

    if (sum < m) {
        cout << -1 << '\n';
        return 0;
    }

    sort(a.begin(), a.end(), greater<ll>());

    auto check = [&](int x) {
        ll res = 0;
        for (int i = 0; i < n; ++i) {
            res += max(0LL, a[i] - i / x);
            if (res >= m) return true;
        }
        return false;
    };

    int l = 0, r = n;
    while (l + 1 < r) {
        int mid = l + (r - l) / 2;
        if (check(mid))
            r = mid;
        else
            l = mid;
    }

    cout << r << '\n';
    return 0;
}

